CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('ADMIN','SUPERVISOR','LEADER','VIEWER'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE work_type AS ENUM ('SHIFT','NON_SHIFT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE attendance_status AS ENUM ('CHECK_IN','CHECK_OUT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id uuid primary key default gen_random_uuid(),username text unique not null,full_name text not null,password_hash text not null,role user_role not null,active boolean not null default true,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS sessions(token_hash text primary key,user_id uuid not null references users(id) on delete cascade,expires_at timestamptz not null,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS employees(emp_id text primary key,barcode text unique not null,name text not null,department text not null,other_department text,work_type work_type not null,work_group text,position text not null,status text not null default 'ACTIVE',home_line text,join_date date,updated_at timestamptz not null default now(),CONSTRAINT barcode_matches_emp CHECK(barcode=emp_id));
CREATE TABLE IF NOT EXISTS lines(line_id text primary key,department text not null,active boolean not null default true);
CREATE TABLE IF NOT EXISTS line_processes(id bigserial primary key,line_id text not null references lines(line_id) on delete cascade,process text not null,required_count int not null default 1 check(required_count>=0),unique(line_id,process));
CREATE TABLE IF NOT EXISTS employee_skills(id bigserial primary key,emp_id text not null references employees(emp_id) on delete cascade,line_id text not null references lines(line_id) on delete cascade,process text not null,priority int not null check(priority>0),unique(emp_id,line_id,process),unique(emp_id,priority));
CREATE TABLE IF NOT EXISTS shifts(shift_code text primary key,label text not null,start_time time not null,end_time time not null,scan_open_minutes int not null default 60,late_after_minutes int not null default 15,scan_close_minutes int not null default 720,active boolean not null default true);
INSERT INTO shifts VALUES('1','Shift 1','08:00','20:00',60,15,720,true),('2','Shift 2','20:00','08:00',60,15,720,true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS daily_plans(id bigserial primary key,work_date date not null,shift_code text not null references shifts(shift_code),created_by uuid references users(id),created_at timestamptz not null default now(),unique(work_date,shift_code));
CREATE TABLE IF NOT EXISTS daily_plan_lines(plan_id bigint not null references daily_plans(id) on delete cascade,line_id text not null references lines(line_id),primary key(plan_id,line_id));
CREATE TABLE IF NOT EXISTS shared_cell_leaders(emp_id text primary key references employees(emp_id) on delete cascade,main_line text references lines(line_id));
CREATE TABLE IF NOT EXISTS shared_cell_leader_lines(emp_id text not null references shared_cell_leaders(emp_id) on delete cascade,line_id text not null references lines(line_id),primary key(emp_id,line_id));
CREATE TABLE IF NOT EXISTS scan_events(id bigserial primary key,employee_code text not null,source text not null,device_id text,payload jsonb not null default '{}',status text not null default 'RECEIVED',processed_at timestamptz,error text,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS attendance(id uuid primary key default gen_random_uuid(),emp_id text not null references employees(emp_id),work_date date not null,shift_code text not null,check_in_at timestamptz not null,check_out_at timestamptz,status attendance_status not null default 'CHECK_IN',late boolean not null default false,line_id text,job text,waiting boolean not null default false,waiting_since timestamptz,waiting_reason text,source text not null default 'MANUAL',scan_event_id bigint references scan_events(id),correction_required boolean not null default false,updated_at timestamptz not null default now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_open_attendance_emp ON attendance(emp_id) WHERE check_out_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_attendance_date_shift ON attendance(work_date,shift_code);
CREATE TABLE IF NOT EXISTS assignments(id uuid primary key default gen_random_uuid(),attendance_id uuid not null references attendance(id) on delete cascade,emp_id text not null references employees(emp_id),work_date date not null,shift_code text not null,line_id text not null references lines(line_id),process text not null,assignment_source text not null,locked boolean not null default true,active boolean not null default true,reason text,created_at timestamptz not null default now(),ended_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS uq_emp_assignment ON assignments(emp_id,work_date,shift_code) WHERE active;
CREATE TABLE IF NOT EXISTS waiting_queue(attendance_id uuid primary key references attendance(id) on delete cascade,emp_id text not null references employees(emp_id),work_date date not null,shift_code text not null,reason text not null,skill_targets jsonb not null default '[]',waiting_since timestamptz not null default now());
CREATE INDEX IF NOT EXISTS idx_wait_fifo ON waiting_queue(work_date,shift_code,waiting_since);
CREATE TABLE IF NOT EXISTS approvals(id uuid primary key default gen_random_uuid(),kind text not null,requested_by uuid not null references users(id),emp_id text references employees(emp_id),payload jsonb not null default '{}',status text not null default 'PENDING',reason text,decided_by uuid references users(id),decided_at timestamptz,created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS planned_absences(id uuid primary key default gen_random_uuid(),emp_id text not null references employees(emp_id),start_at timestamptz not null,end_at timestamptz not null,kind text not null,note text,created_by uuid references users(id));
CREATE TABLE IF NOT EXISTS audit_log(id bigserial primary key,actor_id uuid references users(id),actor_name text,action text not null,entity_type text,entity_id text,detail jsonb not null default '{}',correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());
CREATE TABLE IF NOT EXISTS system_settings(key text primary key,value jsonb not null,updated_by uuid references users(id),updated_at timestamptz not null default now());
INSERT INTO system_settings(key,value) VALUES
('placement','{"allowSkillOverride":true,"waitingAutoPlace":true,"waitingCountsAsWorking":false,"sharedClCoverage":"ALL"}'),
('checkout','{"mode":"AUTO","autoCheckoutMinutes":0,"autoCloseStale":true}'),
('nonShift','{"start":"08:00","end":"17:00"}'),
('backup','{"enabled":true,"schedule":"DAILY","time":"23:00","retainDays":30}') ON CONFLICT DO NOTHING;
